\title{The Projective Geometry of KL-Regularised Alignment\\[4pt]
\large Isometry, sharp total-variation contraction, free-energy duality,\\
and the submodular lattice of symbolic constraints}
\author{Aristotle}
\date{20 August 2026}

\begin{document}
\maketitle

\begin{abstract}
We develop a complete metric geometry for the reinforcement-learning-from-human-feedback
objective with a pre-training mix-in,
\[
J_{\beta,\gamma}(p) \;=\; \E_{p}[r] \;-\; \beta\,\KL(p\|\Ref) \;+\; \gamma\,\E_{\pre}[\log p],
\]
over policies on a finite output alphabet. Our central structural result is that,
for $\gamma = 0$, the alignment map $r \mapsto \pi_\beta(r)$ carrying a reward
model to its optimal KL-regularised policy is an \emph{exact isometry} from the
space of rewards modulo additive constants, equipped with the oscillation
seminorm $\osc(f) = \max f - \min f$ scaled by $1/\beta$, onto the open
probability simplex equipped with Birkhoff's Hilbert projective metric
$d_H(p,q) = \osc(\log(p/q))$:
\[
d_H\big(\pi_\beta(r_1), \pi_\beta(r_2)\big) \;=\; \frac{\osc(r_1-r_2)}{\beta}.
\]
Building on this we prove a \emph{sharp} Hilbert-to-total-variation comparison,
$\TV{p-q} \le \tanh(d_H(p,q)/4)$, whose extremal structure reduces to the single
square $(vw-1)^2 \ge 0$. Combining the two yields the misspecification bound
$\TV{\pi_\beta(r_1)-\pi_\beta(r_2)} \le \tanh(\osc(r_1-r_2)/4\beta) < 1$:
aligned policies for two reward models are never mutually singular, however
badly the reward models disagree. We further establish an envelope duality
identifying the aligned policy as the reward-gradient of the free energy, both
annealing limits with explicit rates, an exact identity for the pre-training
mix-in at the optimum (with a necessary and sufficient no-regression criterion
and a $\gamma\,\osc(r)/\beta$ budget), a variational principle for hard symbolic
constraints together with monotonicity and submodularity of the constrained
value on the Boolean lattice of admissible sets, and an additive drift budget
for iterated alignment with a characterisation of its equality case.
\end{abstract}

\section{Introduction}

Contemporary alignment of a generative model proceeds in two stages. A
supervised fine-tuned model provides a \emph{reference policy} $\Ref$; a learned
reward model $r$ scores candidate outputs; and the policy is then re-optimised
for the composite objective
\[
J_{\beta,\gamma}(p) \;=\; \underbrace{\E_{p}[r]}_{\text{reward}} \;-\; \underbrace{\beta\,\KL(p\|\Ref)}_{\text{trust region}} \;+\; \underbrace{\gamma\,\E_{\pre}[\log p]}_{\text{pre-training mix-in}}.
\]
The KL term is a leash preventing reward hacking and mode collapse; the mix-in
term prevents regression on general capabilities. The coefficients $\beta>0$ and
$\gamma\ge0$ are, in practice, chosen empirically. This paper asks what they
\emph{are}, mathematically, and answers with a metric geometry in which $\beta$
is literally a scale factor.

\paragraph{Contributions.}
\begin{enumerate}
\item \textbf{Isometry} (Theorem~\ref{thm:iso}): alignment is a distance-preserving
bijection between $(\R^\iota/\R\mathbf{1},\ \osc/\beta)$ and the open simplex
under the Hilbert projective metric.
\item \textbf{Sharp contraction} (Theorem~\ref{thm:tanh}):
$\TV{p-q}\le\tanh(d_H(p,q)/4)$, improving the naive $e^{d_H}-1$ to a bound that
is always ${<}\,1$.
\item \textbf{Free-energy duality and annealing} (Theorems~\ref{thm:envelope},
\ref{thm:cold}, \ref{thm:hot}).
\item \textbf{Exact pre-training law} (Theorems~\ref{thm:ptx}--\ref{thm:budget}).
\item \textbf{Symbolic constraint lattice} (Theorems~\ref{thm:cvp}--\ref{thm:price}).
\item \textbf{Drift budget} for iterated alignment (Theorems~\ref{thm:drift}--\ref{thm:strict}).
\item \textbf{Goodhart regret} (Theorem~\ref{thm:goodhart}): optimising a proxy
reward within $M$ of the truth costs at most $2M$, uniformly in $\beta$.
\end{enumerate}

The exponential tilt and its free energy are the classical Gibbs variational
principle; the Hilbert projective metric and the contraction constant
$\tanh(d/4)$ originate in Birkhoff's theory of positive operators. The novelty
here is the identification of that metric as \emph{the} natural metric on the
space of aligned policies, in which alignment is an isometry with scale
$1/\beta$, and the consequences for misspecification, drift accounting and
capability regression.

\section{Setting and notation}

Throughout, $\iota$ is a finite, non-empty set of outputs (responses to a fixed
prompt).

\begin{definition}[Policies]
A \emph{policy} is $p\in\R^\iota$ with $p_i\ge0$ and $\sum_i p_i=1$; it is
\emph{strictly positive} if $p_i>0$ for all $i$. Write $\Delta^\circ$ for the
strictly positive policies.
\end{definition}

\begin{definition}[Reference, reward, pre-training data]
The reference policy $\Ref\in\Delta^\circ$ is fixed; a \emph{reward model} is an
arbitrary $r:\iota\to\R$; the pre-training distribution $\pre$ is a policy.
\end{definition}

\begin{definition}[Objective]
For $\beta>0$,
\[
J_\beta(p) = \sum_i p_i r_i - \beta\,\KL(p\|\Ref), \qquad
\PTX_\gamma(p) = \gamma\sum_i \pre_i \log p_i,
\]
with $\KL(p\|q)=\sum_i p_i\log(p_i/q_i)$ and $0\log 0 = 0$; the full objective is
$J_{\beta,\gamma}=J_\beta+\PTX_\gamma$.
\end{definition}

\begin{definition}[Partition function, tilt, free energy]
\[
Z_\beta(r)=\sum_i \Ref_i e^{r_i/\beta}, \qquad
\pi_\beta(r)_i=\frac{\Ref_i e^{r_i/\beta}}{Z_\beta(r)}, \qquad
F(\beta,r)=\beta\log Z_\beta(r).
\]
\end{definition}

\begin{proposition}[Gibbs variational principle]\label{prop:gibbs}
For every policy $p$, $J_\beta(p)\le F(\beta,r)$, with equality iff
$p=\pi_\beta(r)$.
\end{proposition}

\begin{proof}[Proof sketch]
Substituting the definition of $\pi_\beta(r)$ gives the completion of the square
$J_\beta(p)=F(\beta,r)-\beta\,\KL\big(p\,\|\,\pi_\beta(r)\big)$; conclude by
non-negativity of relative entropy and its equality case.
\end{proof}

\section{Two metrics on rewards and policies}

Since $\pi_\beta(r+c\mathbf{1})=\pi_\beta(r)$, reward models matter only modulo
constants.

\begin{definition}
$\osc(f)=\max_i f_i-\min_i f_i$.
\end{definition}

\begin{proposition}[Seminorm axioms]\label{prop:osc}
For all $f,g$, all $c\in\R$ and $\lambda>0$:
(i) $\osc(f)\ge0$ and $f_i-f_j\le\osc(f)$;
(ii) $\osc(f+c\mathbf{1})=\osc(f)$;
(iii) $\osc(\lambda f)=\lambda\osc(f)$;
(iv) $\osc(f+g)\le\osc(f)+\osc(g)$;
(v) $\osc(-f)=\osc(f)$;
(vi) $|f_i|\le M$ for all $i$ implies $\osc(f)\le 2M$;
(vii) $\osc(f)=0$ iff $f$ is constant.
\end{proposition}

\begin{proof}[Proof sketch]
Elementary manipulations of $\max$ and $\min$: (iv) from
$\max(f+g)\le\max f+\max g$ and $\min(f+g)\ge\min f+\min g$; (v) from
$\max(-f)=-\min f$; (iii) from positivity of $\lambda$.
\end{proof}

By induction, (iv) extends to $\osc\big(\sum_{k<n}f^{(k)}\big)\le\sum_{k<n}\osc(f^{(k)})$.

\begin{definition}[Hilbert projective metric]
For $p,q\in\Delta^\circ$,
$\displaystyle d_H(p,q)=\osc\!\left(\log\frac{p}{q}\right)=\max_i\log\frac{p_i}{q_i}-\min_i\log\frac{p_i}{q_i}$.
\end{definition}

\begin{proposition}[Pseudometric axioms]
On $\Delta^\circ$: $d_H\ge0$, $d_H(p,p)=0$, $d_H(p,q)=d_H(q,p)$ and
$d_H(p,q)\le d_H(p,t)+d_H(t,q)$. Moreover $d_H(p,q)=0$ implies $p=q$.
\end{proposition}

\begin{proof}[Proof sketch]
Symmetry is Proposition~\ref{prop:osc}(v) applied to $\log(p/q)=-\log(q/p)$; the
triangle inequality is subadditivity applied to
$\log(p/q)=\log(p/t)+\log(t/q)$; vanishing forces $\log(p/q)$ constant, hence
$p=q$ after normalisation.
\end{proof}

\begin{definition}[Total variation]
$\TV{p-q}=\tfrac12\sum_i|p_i-q_i|=\max_{A\subseteq\iota}\big(p(A)-q(A)\big)$.
\end{definition}

\section{Alignment is an isometry}

\begin{lemma}[Log-ratio of tilts]\label{lem:logratio}
For all $r_1,r_2$ and all $i$,
$\displaystyle \log\frac{\pi_\beta(r_1)_i}{\pi_\beta(r_2)_i}=\frac{r_{1,i}-r_{2,i}}{\beta}+\log\frac{Z_\beta(r_2)}{Z_\beta(r_1)}$.
\end{lemma}

\begin{proof}[Proof sketch]
The factor $\Ref_i$ cancels, the exponentials combine, and the partition
functions contribute an $i$-independent term.
\end{proof}

\begin{theorem}[Exact isometry]\label{thm:iso}
For every $\beta>0$, every $\Ref\in\Delta^\circ$ and all $r_1,r_2$,
\[
d_H\big(\pi_\beta(r_1),\pi_\beta(r_2)\big)=\frac{\osc(r_1-r_2)}{\beta}.
\]
\end{theorem}

\begin{proof}[Proof sketch]
By Lemma~\ref{lem:logratio} the log-ratio equals $\beta^{-1}(r_1-r_2)$ plus a
constant; oscillation ignores constants and is positively homogeneous.
\end{proof}

\begin{corollary}[Displacement from the reference]\label{cor:disp}
$d_H(\pi_\beta(r),\Ref)=\osc(r)/\beta$.
\end{corollary}

\begin{proof}[Proof sketch]
Take $r_2=0$ and note $\pi_\beta(0)=\Ref$.
\end{proof}

\begin{corollary}[Kernel of alignment]
$\pi_\beta(r_1)=\pi_\beta(r_2)$ iff $r_1-r_2$ is constant.
\end{corollary}

Theorem~\ref{thm:iso} upgrades the algebraic fact that tilting is a free
transitive action of $\R^\iota/\R\mathbf{1}$ on $\Delta^\circ$ to a metric one:
the action is by isometries with scale $1/\beta$. Interpretively, $\beta$ is the
exchange rate between reward spread and policy displacement.

\section{From Hilbert distance to total variation: the sharp constant}

If $d_H(p,q)=d$ then $p_i\le e^{d}q_i$ for all $i$, whence the naive bound
\begin{equation}\label{eq:naive}
\TV{p-q}\le e^{d}-1,
\end{equation}
which is vacuous for $d>\log 2$. The defect is diagnosable: \eqref{eq:naive}
uses only the upper ratio bound and discards the lower bound $vq\le p$.

\begin{lemma}[Birkhoff two-constraint bound]\label{lem:birkhoff}
Let $v\le1$, $w\ge1$, $x\ge0$ and suppose $t\le(vw^2-1)x$ and $t\le(1-v)(1-x)$.
Then $t\le\dfrac{w-1}{w+1}$.
\end{lemma}

\begin{proof}[Proof sketch]
If $vw^2\le1$ then $t\le0\le(w-1)/(w+1)$. Otherwise $1-v\ge0$ and $vw^2-1>0$;
the positive combination $(1-v)\cdot\text{(first)}+(vw^2-1)\cdot\text{(second)}$
eliminates $x$ and gives
$t\,[(1-v)+(vw^2-1)]\le(vw^2-1)(1-v)$. The bracket equals
$v(w^2-1)=v(w-1)(w+1)$, and the exact identity
\[
v(w-1)^2-(vw^2-1)(1-v)=(vw-1)^2\ \ge\ 0
\]
bounds the right-hand side by $v(w-1)^2$. Since $vw^2>1$ and $v\le1$ force
$w>1$, division is legitimate and yields $t\le(w-1)/(w+1)$.
\end{proof}

\begin{theorem}[Sharp Hilbert--TV comparison]\label{thm:tanh}
For $p,q\in\Delta^\circ$ with $d=d_H(p,q)$,
\[
\TV{p-q}\;\le\;\frac{e^{d/2}-1}{e^{d/2}+1}\;=\;\tanh\!\Big(\frac{d}{4}\Big).
\]
\end{theorem}

\begin{proof}[Proof sketch]
Let $L_i=\log(p_i/q_i)$, $S=\max_i L_i$, $I=\min_i L_i$, $d=S-I$, and set
$u=e^{S}$, $v=e^{I}$, $w=e^{d/2}$, so $u=vw^2$ and $w\ge1$. Since both are
probability vectors, some $j$ has $p_j\le q_j$, hence $I\le0$ and $v\le1$.
Pointwise $vq_i\le p_i\le uq_i$. Put $A=\{i:q_i\le p_i\}$, $a=p(A)$, $x=q(A)$;
then $\TV{p-q}=a-x$ because $\sum_i(p_i-q_i)=0$ and the positive part is carried
by $A$. Summing the upper bound over $A$ gives $a\le ux$, i.e.
$a-x\le(vw^2-1)x$; summing the lower bound over $A^c$ gives $v(1-x)\le1-a$, i.e.
$a-x\le(1-v)(1-x)$. Apply Lemma~\ref{lem:birkhoff} with $t=a-x$.
\end{proof}

\begin{theorem}[Reward-model misspecification]\label{thm:missp}
For all $r_1,r_2$,
\[
\TV{\pi_\beta(r_1)-\pi_\beta(r_2)}\;\le\;\tanh\!\left(\frac{\osc(r_1-r_2)}{4\beta}\right).
\]
\end{theorem}

\begin{proof}[Proof sketch]
Compose Theorem~\ref{thm:iso} with Theorem~\ref{thm:tanh}.
\end{proof}

\begin{proposition}[Sharpness]\label{prop:sharp}
The constant $\tanh(d/4)$ cannot be improved. For $d>0$ set $\theta=e^{d/2}$ and
\[
p=\left(\frac{\theta}{1+\theta},\ \frac{1}{1+\theta}\right),\qquad
q=\left(\frac{1}{1+\theta},\ \frac{\theta}{1+\theta}\right).
\]
The two likelihood ratios are $\theta$ and $\theta^{-1}$, so $d_H(p,q)=2\log\theta=d$
while $\TV{p-q}=(\theta-1)/(\theta+1)=\tanh(d/4)$. The extremal configuration is
exactly the equality case $vw=1$ of the square in Lemma~\ref{lem:birkhoff}. Since
any two strictly positive policies are tilts of any strictly positive reference,
the bound of Theorem~\ref{thm:missp} is attained as well.
\end{proposition}

\begin{proof}[Proof sketch]
Maximise $a-x$ over two-point pairs $p=(a,1-a)$, $q=(x,1-x)$ with fixed odds
ratio $e^{d}=\frac{a(1-x)}{x(1-a)}$. With $u=x/(1-x)$ and $a=\frac{e^du}{1+e^du}$,
the objective $\frac{e^du}{1+e^du}-\frac{u}{1+u}$ is maximised at $u=e^{-d/2}$.
\end{proof}

\begin{corollary}[No mutual singularity]
$\TV{\pi_\beta(r_1)-\pi_\beta(r_2)}<1$ always, since $(E-1)/(E+1)<1$ for $E>0$.
\end{corollary}

\section{Free-energy duality, annealing, and Goodhart regret}

\begin{theorem}[Envelope / Danskin duality]\label{thm:envelope}
For $\beta>0$, $\Ref\in\Delta^\circ$ and any $r,s$, the map $t\mapsto F(\beta,r+ts)$
is differentiable at $0$ with
\[
\left.\frac{d}{dt}\right|_{t=0}F(\beta,r+ts)=\sum_i\pi_\beta(r)_i s_i=\E_{\pi_\beta(r)}[s].
\]
\end{theorem}

\begin{proof}[Proof sketch]
Differentiate $Z_\beta(r+ts)$ termwise to obtain $\sum_i\Ref_i e^{r_i/\beta}s_i/\beta$
at $t=0$; then $\frac{d}{dt}\beta\log Z=\beta\dot Z/Z=\E_{\pi_\beta(r)}[s]$.
\end{proof}

\begin{proposition}[Elementary properties of $F$]\label{prop:F}
(i) $F(\beta,r+c\mathbf{1})=F(\beta,r)+c$;
(ii) $r_1\le r_2$ implies $F(\beta,r_1)\le F(\beta,r_2)$;
(iii) $|r_{1,i}-r_{2,i}|\le M$ implies $F(\beta,r_1)-F(\beta,r_2)\le M$;
(iv) $\E_{\Ref}[r]\le F(\beta,r)$.
\end{proposition}

\begin{proof}[Proof sketch]
(i) the shift multiplies $Z$ by $e^{c/\beta}$; (ii) monotonicity of $Z$ and
$\log$; (iii) combine (ii) with (i); (iv) Jensen, or
Proposition~\ref{prop:gibbs} with $p=\Ref$.
\end{proof}

\begin{theorem}[Cold limit: reward maximisation]\label{thm:cold}
For $\beta>0$,
\[
\max_i r_i+\beta\log\Big(\min_i \Ref_i\Big)\ \le\ F(\beta,r)\ \le\ \max_i r_i,
\]
hence $F(\beta,r)\to\max_i r_i$ as $\beta\to0^+$.
\end{theorem}

\begin{proof}[Proof sketch]
Upper: $Z\le e^{\max r/\beta}$ termwise. Lower: keep the maximising term,
$Z\ge(\min_j\Ref_j)e^{\max r/\beta}$. Apply $\beta\log$ and squeeze.
\end{proof}

\begin{theorem}[Hot limit: return to the reference]\label{thm:hot}
If $|r_i|\le M$ for all $i$ with $M>0$ and $\beta\ge M$, then
\[
0\ \le\ F(\beta,r)-\E_{\Ref}[r]\ \le\ \frac34\frac{M^2}{\beta},
\]
hence $F(\beta,r)\to\E_{\Ref}[r]$ as $\beta\to\infty$.
\end{theorem}

\begin{proof}[Proof sketch]
Left: Proposition~\ref{prop:F}(iv). Right: Taylor's theorem gives
$e^u\le1+u+\tfrac34u^2$ on $|u|\le1$; apply with $u=r_i/\beta$ and average
against $\Ref$ to get $Z\le1+\E_{\Ref}[r]/\beta+\tfrac34M^2/\beta^2$; then
$\log Z\le Z-1$ and multiply by $\beta$.
\end{proof}

\begin{theorem}[Goodhart / proxy-reward regret]\label{thm:goodhart}
If $|r_i-\hat r_i|\le M$ for all $i$, then the true regularised value of the
proxy-optimal policy satisfies
$F(\beta,r)-J_\beta\big(\pi_\beta(\hat r)\big)\le 2M$, independently of $\beta$.
\end{theorem}

\begin{proof}[Proof sketch]
With $q=\pi_\beta(\hat r)$, Proposition~\ref{prop:gibbs} for $\hat r$ gives that
the proxy objective at $q$ equals $F(\beta,\hat r)$; swapping $\hat r$ for $r$
inside the expectation costs at most $\sum_i q_i|r_i-\hat r_i|\le M$; and
$F(\beta,r)-F(\beta,\hat r)\le M$ by Proposition~\ref{prop:F}(iii).
\end{proof}

\section{The pre-training mix-in, exactly}

\begin{theorem}[Exact pre-training identity]\label{thm:ptx}
For $\beta>0$, $\Ref\in\Delta^\circ$ and any policy $\pre$,
\[
\sum_i\pre_i\log\pi_\beta(r)_i=\sum_i\pre_i\log\Ref_i+\frac{\E_{\pre}[r]-F(\beta,r)}{\beta}.
\]
\end{theorem}

\begin{proof}[Proof sketch]
Pointwise $\log\pi_\beta(r)_i=\log\Ref_i+r_i/\beta-\log Z_\beta(r)$; average
against $\pre$ using $\sum_i\pre_i=1$, and substitute
$\log Z_\beta(r)=F(\beta,r)/\beta$.
\end{proof}

\begin{theorem}[Exact no-regression criterion]\label{thm:noreg}
For $\beta>0$, $\gamma>0$,
\[
\PTX_\gamma(\Ref)\le\PTX_\gamma\big(\pi_\beta(r)\big)
\iff
F(\beta,r)\le\E_{\pre}[r].
\]
\end{theorem}

\begin{proof}[Proof sketch]
By Theorem~\ref{thm:ptx} the difference is
$\gamma(\E_{\pre}[r]-F(\beta,r))/\beta$, whose sign is that of
$\E_{\pre}[r]-F(\beta,r)$.
\end{proof}

\begin{theorem}[Regression budget]\label{thm:budget}
For $\beta>0$, $\gamma\ge0$,
$\PTX_\gamma(\Ref)-\PTX_\gamma\big(\pi_\beta(r)\big)\le\gamma\,\osc(r)/\beta$.
\end{theorem}

\begin{proof}[Proof sketch]
$F(\beta,r)\le\max_i r_i$ (Theorem~\ref{thm:cold}) and $\E_{\pre}[r]\ge\min_i r_i$,
so $F(\beta,r)-\E_{\pre}[r]\le\osc(r)$; insert into Theorem~\ref{thm:ptx}.
\end{proof}

Comparing with Corollary~\ref{cor:disp}: capability regression and policy drift
are the same quantity $\osc(r)/\beta$ in different units, related by $\gamma$.

\section{Hard symbolic constraints: a submodular lattice}

\begin{definition}[Constrained objects]
For $\emptyset\ne S\subseteq\iota$,
\[
Z_S=\sum_{i\in S}\Ref_i e^{r_i/\beta},\qquad
F_S=\beta\log Z_S,\qquad
\pi^S_\beta(r)_i=\begin{cases}\Ref_i e^{r_i/\beta}/Z_S,& i\in S,\\ 0,& i\notin S.\end{cases}
\]
\end{definition}

\begin{theorem}[Constrained variational principle]\label{thm:cvp}
For every policy $p$ supported in $S$, $J_\beta(p)\le F_S(\beta,r)$, and
$J_\beta(\pi^S_\beta(r))=F_S(\beta,r)$.
\end{theorem}

\begin{proof}[Proof sketch]
Restricting all sums to $S$, the same completion of the square as in
Proposition~\ref{prop:gibbs} gives
$J_\beta(p)=F_S(\beta,r)-\beta\KL\big(p\,\|\,\pi^S_\beta(r)\big)$.
\end{proof}

\begin{theorem}[Filtering commutes with alignment]\label{thm:commute}
For $i\in S$,
$\displaystyle \pi^S_\beta(r)_i=\frac{\pi_\beta(r)_i}{\sum_{j\in S}\pi_\beta(r)_j}$.
\end{theorem}

\begin{proof}[Proof sketch]
Both sides equal $\Ref_i e^{r_i/\beta}/Z_S$ after clearing the common factor
$Z_\beta(r)$.
\end{proof}

\begin{theorem}[Monotonicity]\label{thm:mono}
If $\emptyset\ne S\subseteq T$ then $F_S(\beta,r)\le F_T(\beta,r)$.
\end{theorem}

\begin{theorem}[Submodularity: diminishing returns]\label{thm:submod}
If $S\cap T\ne\emptyset$ then
$F_{S\cup T}+F_{S\cap T}\le F_S+F_T$.
\end{theorem}

\begin{proof}[Proof sketch]
The partition function is modular, $Z_{S\cup T}+Z_{S\cap T}=Z_S+Z_T$, and
$Z_{S\cap T}\le\min(Z_S,Z_T)$. Substituting the first relation gives the exact
factorisation
\[
Z_SZ_T-Z_{S\cup T}Z_{S\cap T}=(Z_S-Z_{S\cap T})(Z_T-Z_{S\cap T})\ \ge\ 0 .
\]
Take logarithms and multiply by $\beta>0$.
\end{proof}

\begin{theorem}[Price of a rule set]\label{thm:price}
For $\emptyset\ne S\subseteq\iota$,
\[
F(\beta,r)-F_S(\beta,r)\ \le\ \osc(r)-\beta\log\Ref(S),\qquad \Ref(S)=\sum_{i\in S}\Ref_i .
\]
\end{theorem}

\begin{proof}[Proof sketch]
Bound $F\le\max_i r_i$ (Theorem~\ref{thm:cold}) and
$Z_S\ge\Ref(S)e^{\min r/\beta}$, so $F_S\ge\beta\log\Ref(S)+\min_i r_i$.
\end{proof}

\section{Iterated alignment and the drift budget}

Because tilting is additive in the reward, the state after $n$ rounds with
rewards $r^{(0)},\dots,r^{(n-1)}$ is $\pi_n=\pi_\beta\big(\sum_{k<n}r^{(k)}\big)$.

\begin{theorem}[One round is a translation]
$d_H\big(\pi_\beta(r+s),\pi_\beta(r)\big)=\osc(s)/\beta$, independently of $r$.
\end{theorem}

\begin{theorem}[Drift budget]\label{thm:drift}
$\displaystyle d_H(\pi_n,\Ref)\le\frac{1}{\beta}\sum_{k=0}^{n-1}\osc\big(r^{(k)}\big)$,
and hence
$\TV{\pi_n-\Ref}\le\tanh\Big(\frac{1}{4\beta}\sum_{k<n}\osc(r^{(k)})\Big)$.
\end{theorem}

\begin{proof}[Proof sketch]
Corollary~\ref{cor:disp} gives $d_H(\pi_n,\Ref)=\osc(\sum_{k<n}r^{(k)})/\beta$;
apply finite subadditivity of $\osc$ and then Theorem~\ref{thm:tanh}.
\end{proof}

\begin{theorem}[Equality case]
Equality holds exactly when
$\osc\big(\sum_{k<n}r^{(k)}\big)=\sum_{k<n}\osc(r^{(k)})$, i.e.\ when successive
rounds never cancel.
\end{theorem}

\begin{theorem}[Strictness in general]\label{thm:strict}
For any $s$ with $\osc(s)>0$, the two-round sequence $(s,-s)$ satisfies
$d_H(\pi_2,\Ref)=0$ while the budget equals $2\osc(s)/\beta>0$.
\end{theorem}

Thus no drift-accounting scheme inspecting rounds individually can improve on
Theorem~\ref{thm:drift}.

\section{Algorithms}

\paragraph{Calibrating $\beta$ from a drift target.}
Given $r$ and a target Hilbert displacement $\delta$, Corollary~\ref{cor:disp}
gives exactly $\beta^\star=\osc(r)/\delta$. For a total-variation target
$\tau\in(0,1)$, inverting Theorem~\ref{thm:missp} gives the conservative choice
$\beta^\star=\osc(r)/\big(4\artanh\tau\big)$. Cost $O(|\iota|)$.

\paragraph{Greedy symbolic rule relaxation.}
Monotonicity and submodularity (Theorems~\ref{thm:mono}, \ref{thm:submod}) make
greedy selection of relaxations by marginal gain in $F_S$ a principled
procedure, with the classical guarantee for monotone submodular maximisation
under a cardinality constraint. Cost $O(mK|\iota|)$ for $m$ selections among $K$
candidate rules.

\paragraph{Drift ledger.}
Maintain $B_n=\beta^{-1}\sum_{k<n}\osc(r^{(k)})$ and
$D_n=\beta^{-1}\osc\big(\sum_{k<n}r^{(k)}\big)$. Then $D_n\le B_n$ always, $D_n$
is the exact drift, and $B_n-D_n$ quantifies inter-round cancellation. Cost
$O(|\iota|)$ per round.

\section{Discussion}

Theorem~\ref{thm:iso} replaces the intuition ``$\beta$ controls how far the
policy may move'' with an equality: the policy moves \emph{exactly}
$\osc(r)/\beta$. Every downstream statement inherits this scale --- the
misspecification bound $\tanh(\osc(r_1-r_2)/4\beta)$, the regression budget
$\gamma\osc(r)/\beta$, and the drift ledger.

The naive comparison $e^{d}-1$ is not merely loose but qualitatively wrong,
suggesting that large reward disagreement can drive policies to mutual
singularity; Theorem~\ref{thm:tanh} shows total variation saturates strictly
below $1$. In practice this guarantees support overlap between any two aligned
policies from a common reference, which matters for importance sampling between
alignment runs and for off-policy comparison of checkpoints.

\paragraph{Limitations.}
The framework is finite and per-prompt. Strict positivity of the reference is
essential: it is what makes the Hilbert metric finite, and a reference assigning
zero probability to an output makes $d_H$ infinite, correctly reflecting that no
amount of KL-regularised tilting can resurrect an impossible output. The
analysis concerns optima rather than optimisation dynamics;
Theorem~\ref{thm:envelope} is the bridge.

\paragraph{An honest negative result.}
There is no exponential-tilt closed form for the optimum of the full objective
with $\gamma>0$: the stationarity condition mixes $\log p$ with $\pre/p$, so the
optimum is a fixed point rather than a Gibbs measure. This is why Sections~4--6
are stated for $\gamma=0$ while Section~7 evaluates the mix-in \emph{at} the
$\gamma=0$ optimum.

\section{Future work}

\begin{itemize}
\item \emph{Ensembles.} For rewards $r_1,\dots,r_m$ with mean $\bar r$, one
expects the strict contraction
$\max_k d_H(\pi_\beta(\bar r),\pi_\beta(r_k))\le(1-1/m)\max_{k,l}d_H(\pi_\beta(r_k),\pi_\beta(r_l))$,
with equality only when all rewards agree modulo constants. By
Theorem~\ref{thm:iso} this is a statement about the oscillation seminorm on a
quotient space, with no probability in it.
\item \emph{Fixed-point theory for $\gamma>0$.} Characterise the full optimum as
the unique fixed point of an explicit map and bound its Hilbert distance from
$\pi_\beta(r)$ as a function of $\gamma$.
\item \emph{Contraction of the alignment iteration.} Determine when repeated
reward-modelling-plus-alignment is a Birkhoff contraction, giving a unique
aligned fixed point.
\item \emph{Continuous output spaces.} Replace $\max/\min$ by essential
supremum/infimum on a compact space.
\end{itemize}

